#!/usr/bin/env python3
"""Merge report_part1.pdf and report_part2.pdf into combined_report.pdf."""
import os
import shutil
import subprocess
import sys

INPUT_FILES = ["report_part1.pdf", "report_part2.pdf"]
OUTPUT_FILE = "combined_report.pdf"

for f in INPUT_FILES:
    if not os.path.exists(f):
        sys.exit(f"Missing input file: {f}")

# Approach 1: pypdf / PyPDF2
try:
    from pypdf import PdfReader, PdfWriter
except ImportError:
    try:
        from PyPDF2 import PdfReader, PdfWriter
    except ImportError:
        PdfReader = PdfWriter = None

if PdfReader is not None:
    writer = PdfWriter()
    for pdf_file in INPUT_FILES:
        reader = PdfReader(pdf_file)
        print(f"{pdf_file}: {len(reader.pages)} pages")
        for page in reader.pages:
            writer.add_page(page)
    with open(OUTPUT_FILE, "wb") as output:
        writer.write(output)
    print(f"Wrote {OUTPUT_FILE} with {len(writer.pages)} total pages (pypdf)")
    sys.exit(0)

# Approach 2: PyMuPDF (fitz)
try:
    import fitz
except ImportError:
    fitz = None

if fitz is not None:
    merged = fitz.open()
    for pdf_file in INPUT_FILES:
        doc = fitz.open(pdf_file)
        print(f"{pdf_file}: {doc.page_count} pages")
        merged.insert_pdf(doc)
        doc.close()
    merged.save(OUTPUT_FILE)
    print(f"Wrote {OUTPUT_FILE} with {merged.page_count} total pages (PyMuPDF)")
    sys.exit(0)

# Approach 3: command-line tools (qpdf, pdftk, gs)
def run(cmd):
    print("Running:", " ".join(cmd))
    result = subprocess.run(cmd, capture_output=True, text=True)
    if result.returncode != 0:
        print(result.stderr)
        return False
    return True

if shutil.which("qpdf"):
    cmd = ["qpdf", "--empty"] + [f"--pages", *INPUT_FILES, "--", OUTPUT_FILE]
    if run(cmd):
        print(f"Wrote {OUTPUT_FILE} (qpdf)")
        sys.exit(0)

if shutil.which("pdftk"):
    cmd = ["pdftk", *INPUT_FILES, "cat", "output", OUTPUT_FILE]
    if run(cmd):
        print(f"Wrote {OUTPUT_FILE} (pdftk)")
        sys.exit(0)

if shutil.which("gs"):
    cmd = ["gs", "-q", "-dNOPAUSE", "-dBATCH", "-sDEVICE=pdfwrite",
           f"-sOutputFile={OUTPUT_FILE}", *INPUT_FILES]
    if run(cmd):
        print(f"Wrote {OUTPUT_FILE} (ghostscript)")
        sys.exit(0)

sys.exit("No usable PDF merge tool found (tried pypdf, PyPDF2, PyMuPDF, qpdf, pdftk, gs)")

