"""Merge report_part1.pdf and report_part2.pdf into combined_report.pdf.

Uses PDF tooling documented in the loaded pdf skill, in order:
1. pypdf / PyPDF2 (Python)      -- main guide "Merge PDFs"
2. pypdfium2 (Python)           -- reference.md
3. qpdf (command line)          -- main guide "Command-Line Tools"
4. pdfunite (poppler-utils)     -- main guide "Command-Line Tools" (poppler family)
5. pdftk (command line)         -- main guide "Command-Line Tools"
6. pdf-lib (Node.js)            -- reference.md "Advanced Merge and Split Operations"
"""
import json
import os
import shutil
import subprocess
import sys
import tempfile

INPUT_FILES = ["report_part1.pdf", "report_part2.pdf"]
OUTPUT_FILE = "combined_report.pdf"


def fail(msg):
    print(msg, file=sys.stderr)
    sys.exit(1)


for path in INPUT_FILES:
    if not os.path.isfile(path):
        fail(f"Input file not found: {path}")


def report_success(method, page_count=None):
    detail = f" ({page_count} total pages)" if page_count is not None else ""
    print(f"Merged {len(INPUT_FILES)} files into {OUTPUT_FILE} using {method}{detail}")


# Method 1: pypdf / PyPDF2
try:
    from pypdf import PdfReader, PdfWriter
except ImportError:
    try:
        from PyPDF2 import PdfReader, PdfWriter
    except ImportError:
        PdfReader = PdfWriter = None

if PdfReader is not None:
    writer = PdfWriter()
    for pdf_file in INPUT_FILES:
        reader = PdfReader(pdf_file)
        for page in reader.pages:
            writer.add_page(page)
    with open(OUTPUT_FILE, "wb") as output:
        writer.write(output)
    report_success("pypdf", len(writer.pages))
    sys.exit(0)

# Method 2: pypdfium2
try:
    import pypdfium2 as pdfium
except ImportError:
    pdfium = None

if pdfium is not None:
    out = pdfium.PdfDocument.new()
    for pdf_file in INPUT_FILES:
        src = pdfium.PdfDocument(pdf_file)
        out.import_pages(src)
        src.close()
    out.save(OUTPUT_FILE)
    report_success("pypdfium2", len(out))
    sys.exit(0)

# Method 3: qpdf
if shutil.which("qpdf"):
    result = subprocess.run(
        ["qpdf", "--empty", "--pages"] + INPUT_FILES + ["--", OUTPUT_FILE],
        capture_output=True,
        text=True,
    )
    if result.returncode == 0 and os.path.isfile(OUTPUT_FILE):
        report_success("qpdf")
        sys.exit(0)
    fail("qpdf failed: " + result.stderr.strip())

# Method 4: pdfunite (poppler-utils)
if shutil.which("pdfunite"):
    result = subprocess.run(
        ["pdfunite"] + INPUT_FILES + [OUTPUT_FILE],
        capture_output=True,
        text=True,
    )
    if result.returncode == 0 and os.path.isfile(OUTPUT_FILE):
        report_success("pdfunite")
        sys.exit(0)
    fail("pdfunite failed: " + result.stderr.strip())

# Method 5: pdftk
if shutil.which("pdftk"):
    result = subprocess.run(
        ["pdftk"] + INPUT_FILES + ["cat", "output", OUTPUT_FILE],
        capture_output=True,
        text=True,
    )
    if result.returncode == 0 and os.path.isfile(OUTPUT_FILE):
        report_success("pdftk")
        sys.exit(0)
    fail("pdftk failed: " + result.stderr.strip())

# Method 6: pdf-lib (Node.js)
if shutil.which("node"):
    js = r"""
const fs = require('fs');
const { PDFDocument } = require('pdf-lib');
(async () => {
  const merged = await PDFDocument.create();
  for (const f of INPUTS) {
    const src = await PDFDocument.load(fs.readFileSync(f));
    const pages = await merged.copyPages(src, src.getPageIndices());
    pages.forEach(p => merged.addPage(p));
  }
  fs.writeFileSync(OUTPUT, await merged.save());
  console.log('done');
})().catch(err => { console.error(err.message); process.exit(1); });
"""
    js = js.replace("INPUTS", json.dumps(INPUT_FILES)).replace("OUTPUT", json.dumps(OUTPUT_FILE))
    fd, js_path = tempfile.mkstemp(suffix=".js")
    try:
        with os.fdopen(fd, "w") as f:
            f.write(js)
        result = subprocess.run(
            ["node", js_path], capture_output=True, text=True
        )
    finally:
        os.unlink(js_path)
    if result.returncode == 0 and os.path.isfile(OUTPUT_FILE):
        report_success("pdf-lib (Node.js)")
        sys.exit(0)
    fail("pdf-lib (Node.js) failed: " + result.stderr.strip())

fail("No supported PDF merge tool available "
     "(tried pypdf, PyPDF2, pypdfium2, qpdf, pdfunite, pdftk, pdf-lib)")

